from class12_chemistry_opening import pair,section,SOURCE
from class12_chemistry_sync import save
from class12_chemistry_rings import Fig
F=Fig('arrow172');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
K=lambda lang,*v:v[{'en':0,'ur':1,'ps':2}[lang]]
def eq1(lang):
 s=F.start(120)+t(300,40,'N₂ + O₂',16)+F.arrow(380,480,34)+t(540,40,'2NO',16)
 s+=t(260,96,K(lang,'Hydrocarbon','ہائیڈروکاربن','هایدروکاربن')+' + O₂',16)+F.arrow(380,480,90,K(lang,'(limited O₂)','(محدود O₂)','(محدود O₂)'))+t(600,96,'CO + H₂O + '+K(lang,'Energy','توانائی','انرژي'),16)
 return s+'</svg>'
def hb(lang):
 s=F.start(100)+t(260,40,'HbO₂  +  CO',16)+t(240,62,K(lang,'Oxyhaemoglobin','آکسی ہیموگلوبن','اکسي هیموګلوبین'),11)+t(240,76,K(lang,'complex','کمپلیکس','کمپلېکس'),11)+F.arrow(350,460,34)
 s+=t(560,40,'COHb  +  O₂',16)+t(550,62,K(lang,'Carboxyhaemoglobin','کاربوکسی ہیموگلوبن','کاربوکسي هیموګلوبین'),11)+t(550,76,K(lang,'complex','کمپلیکس','کمپلېکس'),11)
 return s+'</svg>'

add('The lightening in air and also in combustion engine of motor vehicles may also cause reaction between stable molecules of N₂ and O₂, producing NO.','ہوا میں آسمانی بجلی اور گاڑیوں کے احتراقی انجن میں بھی N₂ اور O₂ کے پائیدار سالمات کے درمیان تعامل ہو سکتا ہے جس سے NO بنتی ہے۔','په هوا کې برېښنا او د موټرو په سوځونکي انجن کې هم د N₂ او O₂ د ثابتو مالیکولونو ترمنځ تعامل کېدای شي چې NO تولیدوي.')
add('Incomplete combustion of the carbonaceous compounds (hydrocarbons, coal etc.) results in the formation of carbon monoxide; e.g.','کاربن والے مرکبات (ہائیڈروکاربنز، کوئلہ وغیرہ) کے نامکمل احتراق سے کاربن مونو آکسائیڈ بنتی ہے؛ مثلاً','د کاربن لرونکو مرکباتو (هایدروکاربنونو، ډبرینو سکرو او نورو) نابشپړ سوځېدل د کاربن مونو اکساید د جوړېدو لامل کېږي؛ لکه')
visual('chem12-p172-no-co',eq1)
add('CO, like other pollutants such as SOₓ, NOₓ etc, pollute the fresh air. At concentration higher than 750 ppm, CO may cause loss of consciousness or death.','CO دوسری آلودگیوں جیسے SOₓ، NOₓ وغیرہ کی طرح تازہ ہوا کو آلودہ کرتی ہے۔ 750 ppm سے زیادہ ارتکاز پر CO بے ہوشی یا موت کا سبب بن سکتی ہے۔','CO د نورو ککړوونکو لکه SOₓ، NOₓ او نورو په څېر تازه هوا ککړوي. له 750 ppm لوړ غلظت کې CO کېدای شي د بې هوښۍ یا مړینې لامل شي.')
add('Some chemical reactions, occurring in the atmosphere, are involved in the formation of industrial and photochemical smog.','فضا میں ہونے والے بعض کیمیائی تعاملات صنعتی اور فوٹو کیمیکل سموگ کی تشکیل میں شامل ہیں۔','په اتموسفیر کې ځینې پېښېدونکي کیمیاوي تعاملونه د صنعتي او فوټوکیمیکل سموګ په جوړېدو کې ونډه لري.')
add('23.1.2 COₓ, NOₓ, VOCs, SOₓ, O₃ as Air Pollutants','23.1.2 COₓ، NOₓ، VOCs، SOₓ، O₃ بطور فضائی آلودگیاں','23.1.2 COₓ، NOₓ، VOCs، SOₓ، O₃ د هوا د ککړوونکو په توګه','heading')
add('The term air pollutant generally refers to substances that on local and regional scales directly harm animals, plants and people and their artifacts. Clean and dry air contains 78.09% nitrogen, 20.94% oxygen by volume. The remaining 0.97% is comprised of gaseous mixture of CO₂, He, Ar, Kr, Xe and nitrous oxide (N₂O). A wide range of chemicals can pollute the air. They include carbon monoxide, sulphure dioxide, toxic organics, nitrogen oxides and volatile organic compound (VOCs).','فضائی آلودگی کی اصطلاح عموماً ان مادوں کے لیے ہے جو مقامی اور علاقائی سطح پر جانوروں، پودوں، لوگوں اور ان کی بنائی ہوئی اشیا کو براہِ راست نقصان پہنچاتے ہیں۔ صاف اور خشک ہوا میں حجم کے لحاظ سے 78.09% نائٹروجن اور 20.94% آکسیجن ہوتی ہے۔ باقی 0.97% CO₂، He، Ar، Kr، Xe اور نائٹرس آکسائیڈ (N₂O) کے گیسی آمیزے پر مشتمل ہے۔ بہت سے کیمیکلز ہوا کو آلودہ کر سکتے ہیں۔ ان میں کاربن مونو آکسائیڈ، سلفر ڈائی آکسائیڈ، زہریلے نامیاتی مادے، نائٹروجن آکسائیڈز اور اڑنے والے نامیاتی مرکبات (VOCs) شامل ہیں۔','د هوا ککړوونکي اصطلاح عموماً هغو موادو ته ویل کېږي چې په سیمه ییزه او منطقوي کچه ژویو، بوټو، خلکو او د هغوی جوړو شیانو ته مستقیم زیان رسوي. پاکه او وچه هوا د حجم له مخې 78.09% نایټروجن او 20.94% اکسیجن لري. پاتې 0.97% د CO₂، He، Ar، Kr، Xe او نایټرس اکساید (N₂O) له ګازي ګډولې جوړ دي. ډېر کیمیکلونه هوا ککړولی شي. په دې کې کاربن مونو اکساید، سلفر ډای اکساید، زهرجن عضوي مواد، نایټروجن اکسایډونه او الوتونکي عضوي مرکبات (VOCs) شامل دي.')
add('Carbon Monoxide','کاربن مونو آکسائیڈ','کاربن مونو اکساید','heading')
add('Carbon monoxide mainly results from the incomplete combustion of carbonaceous compounds. It is colourless, odourless, toxic gas. It is termed as asphyxiating (suffocating) pollution because it can displace (O₂) bound to hemoglobin (Hb).','کاربن مونو آکسائیڈ بنیادی طور پر کاربن والے مرکبات کے نامکمل احتراق سے بنتی ہے۔ یہ بے رنگ، بے بو اور زہریلی گیس ہے۔ اسے دم گھونٹنے والی آلودگی کہا جاتا ہے کیونکہ یہ ہیموگلوبن (Hb) سے جڑی (O₂) کو ہٹا سکتی ہے۔','کاربن مونو اکساید اساساً د کاربن لرونکو مرکباتو له نابشپړ سوځېدو څخه رامنځته کېږي. دا بې رنګه، بې بویه او زهرجن ګاز دی. د ساه بندوونکې ککړتیا په توګه یادېږي ځکه له هیموګلوبین (Hb) سره تړلی (O₂) بې ځایه کولی شي.')
visual('chem12-p172-carboxyhaemoglobin',hb)
add('The iron (Fe) binding sites in hemoglobin bind carbon monoxide (CO) 320 times more tightly than O₂. The main source of CO to the environment are the vehicle emission, combustion of fuel such as natural gas, coal, or wood. When the concentration of the CO inhaled, reaches 100 ppm, particularly in the closed spaces like tunnels, parking garages etc., it may result in headache and shortness of breath. The severity of the effects depends on the duration of the exposure and level of exertion. At a concentration higher than 750 ppm, loss of consciousness or death may occur.','ہیموگلوبن میں لوہے (Fe) کے جڑنے کے مقامات کاربن مونو آکسائیڈ (CO) کو O₂ کے مقابلے میں 320 گنا زیادہ مضبوطی سے جوڑتے ہیں۔ ماحول میں CO کے بڑے ذرائع گاڑیوں کا اخراج اور قدرتی گیس، کوئلہ یا لکڑی جیسے ایندھن کا جلنا ہیں۔ جب سانس میں لی گئی CO کا ارتکاز 100 ppm تک پہنچ جائے، خاص طور پر سرنگوں، پارکنگ گیراجوں وغیرہ جیسی بند جگہوں میں، تو سر درد اور سانس پھولنے کا باعث بن سکتا ہے۔ اثرات کی شدت سامنے رہنے کی مدت اور مشقت کی سطح پر منحصر ہے۔ 750 ppm سے زیادہ ارتکاز پر بے ہوشی یا موت ہو سکتی ہے۔','په هیموګلوبین کې د اوسپنې (Fe) د نښلېدو ځایونه کاربن مونو اکساید (CO) د O₂ په پرتله 320 ځله ډېر ټینګ نښلوي. چاپېریال ته د CO اصلي سرچینې د موټرو اخراج او د سونګ لکه طبیعي ګاز، ډبرینو سکرو یا لرګي سوځېدل دي. کله چې د تنفس شوي CO غلظت 100 ppm ته ورسېږي، په ځانګړي ډول په تړلو ځایونو لکه تونلونو، د پارکینګ ګراجونو او نورو کې، کېدای شي د سر درد او د ساه لنډۍ لامل شي. د اغېزو شدت د مخ کېدو په موده او د هڅې په کچه پورې اړه لري. له 750 ppm لوړ غلظت کې بې هوښي یا مړینه کېدای شي.')
add('Sulphur Dioxide (SO₂)','سلفر ڈائی آکسائیڈ (SO₂)','سلفر ډای اکساید (SO₂)','heading')
add('The main sources of sulphur dioxide (SO₂) emission to contaminate air, are combustion of coal and the smelting of metals (metallurgy) particularly copper. The sulphur content of the refined petroleum is generally quite low but the sulphur content of coal is quite high. The sulphur in coal is converted to SO₂ during combustion. SO₂ itself is a lung irritant and is harmful to people suffering from respiratory diseases. However, the most damaging health effects in urban atmosphere are not by SO₂ but by the sulphuric acid aerosol formed from its oxidation. Sulphuric acid not only irritates the fine vessels of the pulmonary region, causing them to swell and block the passages, but is also the major contributor to the acid rain.',
 'ہوا کو آلودہ کرنے والے سلفر ڈائی آکسائیڈ (SO₂) کے اخراج کے بڑے ذرائع کوئلے کا جلنا اور دھاتوں (خاص طور پر تانبے) کی گلائی (میٹالرجی) ہیں۔ صاف شدہ پیٹرولیم میں سلفر کی مقدار عموماً کافی کم لیکن کوئلے میں کافی زیادہ ہوتی ہے۔ کوئلے میں موجود سلفر جلنے کے دوران SO₂ میں بدل جاتی ہے۔ SO₂ خود پھیپھڑوں میں جلن پیدا کرتی ہے اور سانس کی بیماریوں میں مبتلا لوگوں کے لیے نقصان دہ ہے۔ تاہم شہری فضا میں صحت کے لیے سب سے زیادہ نقصان دہ اثرات SO₂ سے نہیں بلکہ اس کی تکسید سے بننے والے سلفیورک ایسڈ ایروسول سے ہوتے ہیں۔ سلفیورک ایسڈ نہ صرف پھیپھڑوں کی باریک نالیوں میں جلن پیدا کر کے انہیں سجا دیتا اور راستے بند کر دیتا ہے بلکہ تیزابی بارش کا بڑا سبب بھی ہے۔',
 'هوا ته د ککړوونکي سلفر ډای اکساید (SO₂) د اخراج اصلي سرچینې د ډبرینو سکرو سوځېدل او د فلزاتو (په ځانګړي ډول مسو) ویلې کول (فلزکاري) دي. د تصفیه شوي پټرولیم د سلفر اندازه عموماً ډېره ټیټه ده خو د ډبرینو سکرو د سلفر اندازه ډېره لوړه ده. په ډبرینو سکرو کې سلفر د سوځېدو پر مهال په SO₂ بدلېږي. SO₂ پخپله سږو ته خارښ راوړونکی دی او د تنفسي ناروغیو اخته خلکو ته زیانمن دی. خو په ښاري اتموسفیر کې تر ټولو زیانمنې روغتیايي اغېزې د SO₂ نه بلکې د هغه له اکسیډېشن څخه د جوړ شوي سلفوریک اسید ایروسول له امله دي. سلفوریک اسید نه یوازې د سږو نري رګونه خارښوي، پړسوي او لارې یې بندوي، بلکې د تېزابي باران لوی لامل هم دی.')
add('Nitrogen oxides NOₓ and Volatile Organic Compounds (VOCs)','نائٹروجن آکسائیڈز NOₓ اور اڑنے والے نامیاتی مرکبات (VOCs)','نایټروجن اکسایډونه NOₓ او الوتونکي عضوي مرکبات (VOCs)','heading')
add('NOₓ is a common designation of nitrogen oxides, NO and NO₂. Nitrogen oxide, particularly nitrogen dioxide, is emitted from high temperature combustion processes and is also produced during thunderstorm by natural electric discharge. NOₓ can cause serious health damage to humans, including respiratory diseases. NOₓ is also responsible for smog formation and typical brown clouds or haze that covers large cities which results in poor air quality. NOₓ emission also contributes to acid rain and formation of ground level ozone that can damage animal and plant life. NOₓ reacts with volatile organic compounds in the presence of sunlight and forms ground level ozone which can be transported with wind over longer distance. High level NOₓ concentration can have negative effects on vegetation and causes forest damage.',
 'NOₓ نائٹروجن آکسائیڈز NO اور NO₂ کا عام نام ہے۔ نائٹروجن آکسائیڈ، خاص طور پر نائٹروجن ڈائی آکسائیڈ، زیادہ درجہ حرارت کے احتراقی عمل سے خارج ہوتی ہے اور گرج چمک کے طوفان کے دوران قدرتی برقی اخراج سے بھی بنتی ہے۔ NOₓ انسانوں کی صحت کو سانس کی بیماریوں سمیت شدید نقصان پہنچا سکتی ہے۔ NOₓ سموگ کی تشکیل اور بڑے شہروں پر چھانے والے مخصوص بھورے بادلوں یا دھند کی بھی ذمہ دار ہے جس سے ہوا کا معیار خراب ہوتا ہے۔ NOₓ کا اخراج تیزابی بارش اور زمینی سطح کی اوزون بننے میں بھی حصہ ڈالتا ہے جو جانوروں اور پودوں کو نقصان پہنچا سکتی ہے۔ NOₓ دھوپ کی موجودگی میں اڑنے والے نامیاتی مرکبات سے تعامل کر کے زمینی سطح کی اوزون بناتی ہے جو ہوا کے ساتھ دور تک منتقل ہو سکتی ہے۔ NOₓ کا زیادہ ارتکاز نباتات پر منفی اثر ڈال سکتا ہے اور جنگلات کو نقصان پہنچاتا ہے۔',
 'NOₓ د نایټروجن اکسایډونو NO او NO₂ عام نوم دی. نایټروجن اکساید، په ځانګړي ډول نایټروجن ډای اکساید، د لوړې تودوخې د سوځېدو له عملیو خوشې کېږي او د تندر طوفان پر مهال د طبیعي برېښنايي تخلیې په واسطه هم تولیدېږي. NOₓ کولی شي انسانانو ته د تنفسي ناروغیو په ګډون جدي روغتیايي زیان ورسوي. NOₓ د سموګ د جوړېدو او هغو ځانګړو نسواري ورېځو یا لړې مسؤل هم دی چې لوی ښارونه پوښي او د هوا د کیفیت د خرابېدو لامل کېږي. د NOₓ اخراج د تېزابي باران او د ځمکې د سطحې د اوزون په جوړېدو کې هم ونډه لري چې ژویو او بوټو ته زیان رسولی شي. NOₓ د لمر رڼا په شتون کې له الوتونکو عضوي مرکباتو سره تعامل کوي او د ځمکې د سطحې اوزون جوړوي چې له باد سره لرې ځایونو ته لېږدېدای شي. د NOₓ لوړ غلظت پر نباتاتو منفي اغېز کولی شي او ځنګلونو ته زیان رسوي.')
add('Volatile organic compounds (VOCs) include methane, CH₄. It is an efficient greenhouse gas which contributes to enhance global warming. The major sources of VOCs emission are the industrial processes, solvent utilization and vehicular emission.','اڑنے والے نامیاتی مرکبات (VOCs) میں میتھین CH₄ شامل ہے۔ یہ ایک مؤثر گرین ہاؤس گیس ہے جو عالمی حدت بڑھانے میں حصہ ڈالتی ہے۔ VOCs کے اخراج کے بڑے ذرائع صنعتی عمل، محللات کا استعمال اور گاڑیوں کا اخراج ہیں۔','الوتونکي عضوي مرکبات (VOCs) میتان CH₄ لري. دا یو اغېزمن شنه خونې ګاز دی چې د نړیوالې تودوخې په زیاتولو کې ونډه لري. د VOCs د اخراج اصلي سرچینې صنعتي عملیې، د محللونو کارول او د موټرو اخراج دي.')
add('Ozone (O₃) as Pollutant','اوزون (O₃) بطور آلودگی','اوزون (O₃) د ککړوونکي په توګه','heading')
add('Some VOCs are responsible for ozone production in lower atmosphere at the ground level. Ozone at ground level is quite harmful, producing cracks in rubber, destroying plants, and causing respiratory distress and eye irritation in humans. These effects set in at quite low concentrations, around 100 ppb.','بعض VOCs زمینی سطح پر نچلی فضا میں اوزون کی پیداوار کے ذمہ دار ہیں۔ زمینی سطح پر اوزون کافی نقصان دہ ہے جو ربڑ میں دراڑیں پیدا کرتی، پودوں کو تباہ کرتی اور انسانوں میں سانس کی تکلیف اور آنکھوں میں جلن پیدا کرتی ہے۔ یہ اثرات کافی کم ارتکاز، تقریباً 100 ppb، پر شروع ہو جاتے ہیں۔','ځینې VOCs د ځمکې په سطحه په ښکته اتموسفیر کې د اوزون د تولید مسؤل دي. د ځمکې په سطحه اوزون ډېر زیانمن دی چې په رابړ کې درزونه، د بوټو ویجاړېدل او په انسانانو کې تنفسي ستونزې او د سترګو خارښ رامنځته کوي. دا اغېزې په ډېر ټیټ غلظت، نږدې 100 ppb کې پیلېږي.')
add('The naturally produced ozone in upper troposphere is useful for life as it prevents us from harmful ultraviolet (U.V.) radiations, however, some man-made chemicals like chlorofluorocarbons (CFCs) are harmful to this protective ozone layer. The CFCs are emitted from air conditioners, refrigerators, aerosols sprays, etc. On release into air, CFCs rise to stratosphere where, they come in contact with other gases and through chemical reaction damage the ozone layer. This allows harmful U.V. rays to reach the Earth’s surface and have adverse effects.','بالائی ٹروپوسفیئر میں قدرتی طور پر بننے والی اوزون زندگی کے لیے مفید ہے کیونکہ یہ ہمیں نقصان دہ بالائے بنفشی (U.V.) شعاعوں سے بچاتی ہے، تاہم کلورو فلورو کاربنز (CFCs) جیسے انسانی ساختہ کیمیکلز اس حفاظتی اوزون تہہ کے لیے نقصان دہ ہیں۔ CFCs ایئر کنڈیشنرز، ریفریجریٹرز، ایروسول سپرے وغیرہ سے خارج ہوتی ہیں۔ ہوا میں خارج ہونے پر CFCs سٹریٹوسفیئر تک اٹھتی ہیں جہاں دوسری گیسوں سے رابطے میں آ کر کیمیائی تعامل سے اوزون تہہ کو نقصان پہنچاتی ہیں۔ اس سے نقصان دہ U.V. شعاعیں زمین کی سطح تک پہنچ کر مضر اثرات ڈالتی ہیں۔','په پورتني ټروپوسفیر کې په طبیعي ډول تولید شوی اوزون د ژوند لپاره ګټور دی ځکه موږ د زیانمنو ماورای بنفش (U.V.) وړانګو څخه ساتي، خو ځینې د انسان جوړ کیمیکلونه لکه کلورو فلورو کاربنونه (CFCs) دې ساتونکې اوزون طبقې ته زیانمن دي. CFCs له ایرکنډیشنرونو، یخچالونو، ایروسول سپرېګانو او نورو خوشې کېږي. هوا ته د خوشې کېدو پر مهال CFCs سټراټوسفیر ته پورته کېږي چې هلته له نورو ګازونو سره په تماس کې راځي او د کیمیاوي تعامل له لارې اوزون طبقې ته زیان رسوي. دا زیانمنو U.V. وړانګو ته اجازه ورکوي چې د ځمکې سطحې ته ورسېږي او ناوړه اغېزې ولري.')
